"use strict";let winSc,winH=window.innerHeight,winW=window.innerWidth;const $body=document.getElementsByTagName("body"),$html=document.getElementsByTagName("html");function friendFind(){document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".pet_img_wrap").forEach((e,i)=>{const n=e.querySelector(".swiper-pet-prev"),t=e.querySelector(".swiper-pet-next"),r=`swiper-pet-prev-${i}`,s=`swiper-pet-next-${i}`;n.classList.add(r),t.classList.add(s);new Swiper(e,{spaceBetween:"5%",wrapperClass:"swiper-wrapper",slideClass:"swiper-slide",navigation:{prevEl:`.${r}`,nextEl:`.${s}`}})})})}function layout(){}function main(){new Swiper(".main_slide",{loop:!1,parallax:!0,spaceBetween:"5%"});document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".main_slide_inside").forEach(e=>{const i=e.querySelector(".swiper-inside-prev"),n=e.querySelector(".swiper-inside-next");new Swiper(e,{loop:!1,spaceBetween:0,allowTouchMove:!1,wrapperClass:"swiper-wrapper",slideClass:"swiper-slide",navigation:{prevEl:i,nextEl:n}})})});const e=document.querySelectorAll("#intro .tit_wrap li");new Swiper(".intro_slide",{loop:!1,spaceBetween:"5%",pagination:{el:".swiper-pagination"},on:{slideChange:function(){e.forEach(e=>e.classList.remove("active")),e[this.activeIndex]&&e[this.activeIndex].classList.add("active")}}})}function profile(){document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".profile_img_wrap").forEach((e,i)=>{const n=e.querySelector(".swiper-profile-prev"),t=e.querySelector(".swiper-profile-next"),r=`swiper-profile-prev-${i}`,s=`swiper-profile-next-${i}`;n.classList.add(r),t.classList.add(s);new Swiper(e,{spaceBetween:"5%",wrapperClass:"swiper-wrapper",slideClass:"swiper-slide",navigation:{prevEl:`.${r}`,nextEl:`.${s}`}})})})}window.addEventListener("scroll",e=>{}),window.addEventListener("resize",e=>{winW=window.innerWidth}),layout(),main(),friendFind(),profile();